using System.Data;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.Data.SqlClient;
using TeamsAgent.Core;
namespace TeamsAgent.Persistence;
public sealed class SqlStore(string connectionString, Guid tenant) : IMeetingStore, ITranscriptStore, IContentStore
{
    static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);
    static string Hash(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
    string Id(MeetingKey key) { TenantGuard.Require(tenant, key.TenantId); return Hash(key.MeetingId); }
    async Task<SqlConnection> Open(CancellationToken ct) { var c = new SqlConnection(connectionString); await c.OpenAsync(ct); return c; }
    SqlCommand Command(SqlConnection c, string sql, MeetingKey? key = null, SqlTransaction? tx = null) { var cmd = new SqlCommand(sql, c, tx); cmd.Parameters.AddWithValue("@tenant", tenant); if (key is not null) cmd.Parameters.AddWithValue("@id", Id(key)); return cmd; }
    public async Task<MeetingSession?> GetAsync(MeetingKey key, CancellationToken ct) { await using var c = await Open(ct); using var cmd = Command(c, "SELECT Json FROM Meetings WHERE Tenant=@tenant AND Id=@id AND Created>DATEADD(day,-30,SYSDATETIMEOFFSET())", key); var data = await cmd.ExecuteScalarAsync(ct); return data is string s ? JsonSerializer.Deserialize<MeetingSession>(s, Json) : null; }
    public async Task<MeetingSession> UpdateAsync(MeetingKey key, Func<MeetingSession?, Task<MeetingSession>> update, CancellationToken ct)
    {
        await using var c = await Open(ct); await using var tx = (SqlTransaction)await c.BeginTransactionAsync(IsolationLevel.Serializable, ct);
        using var read = Command(c, "SELECT Json FROM Meetings WITH (UPDLOCK,HOLDLOCK) WHERE Tenant=@tenant AND Id=@id", key, tx);
        var value = await read.ExecuteScalarAsync(ct); var result = await update(value is string s ? JsonSerializer.Deserialize<MeetingSession>(s, Json) : null);
        if (result.Key != key) throw new UnauthorizedAccessException();
        using var write = Command(c, "IF EXISTS(SELECT 1 FROM Meetings WHERE Tenant=@tenant AND Id=@id) UPDATE Meetings SET Json=@json WHERE Tenant=@tenant AND Id=@id ELSE INSERT Meetings(Tenant,Id,Created,Json) VALUES(@tenant,@id,@created,@json)", key, tx);
        write.Parameters.AddWithValue("@json", JsonSerializer.Serialize(result, Json)); write.Parameters.AddWithValue("@created", result.Created); await write.ExecuteNonQueryAsync(ct); await tx.CommitAsync(ct); return result;
    }
    public async Task AppendAsync(TranscriptSegment s, CancellationToken ct)
    {
        await using var c = await Open(ct); using var cmd = Command(c, "INSERT Segments(Tenant,MeetingId,SegmentId,Json) SELECT @tenant,@id,@segment,@json WHERE EXISTS(SELECT 1 FROM Meetings WHERE Tenant=@tenant AND Id=@id AND Created>DATEADD(day,-30,SYSDATETIMEOFFSET())) AND NOT EXISTS(SELECT 1 FROM Segments WITH (UPDLOCK,HOLDLOCK) WHERE Tenant=@tenant AND MeetingId=@id AND SegmentId=@segment)", s.Meeting);
        cmd.Parameters.AddWithValue("@segment", Hash(s.Id)); cmd.Parameters.AddWithValue("@json", JsonSerializer.Serialize(s, Json)); await cmd.ExecuteNonQueryAsync(ct);
    }
    public async Task<IReadOnlyList<TranscriptSegment>> ReadAsync(MeetingKey key, CancellationToken ct) { await using var c = await Open(ct); using var cmd = Command(c, "SELECT s.Json FROM Segments s JOIN Meetings m ON s.Tenant=m.Tenant AND s.MeetingId=m.Id WHERE s.Tenant=@tenant AND s.MeetingId=@id AND m.Created>DATEADD(day,-30,SYSDATETIMEOFFSET())", key); await using var r = await cmd.ExecuteReaderAsync(ct); var segments = new List<TranscriptSegment>(); while (await r.ReadAsync(ct)) segments.Add(JsonSerializer.Deserialize<TranscriptSegment>(r.GetString(0), Json)!); return segments.OrderBy(s => s.Start).ToArray(); }
    public async Task MarkGapAsync(MeetingKey key, TimeSpan offset, CancellationToken ct) => _ = await UpdateAsync(key, s => Task.FromResult((s ?? throw new KeyNotFoundException()) with { Incomplete = true }), ct);
    public async Task<MeetingMinutes?> GetMinutesAsync(MeetingKey key, CancellationToken ct) { await using var c = await Open(ct); using var cmd = Command(c, "SELECT Minutes FROM Meetings WHERE Tenant=@tenant AND Id=@id AND Created>DATEADD(day,-30,SYSDATETIMEOFFSET())", key); return await cmd.ExecuteScalarAsync(ct) is string s ? JsonSerializer.Deserialize<MeetingMinutes>(s, Json) : null; }
    public async Task SaveMinutesAsync(MeetingKey key, MeetingMinutes m, CancellationToken ct) { await using var c = await Open(ct); using var cmd = Command(c, "UPDATE Meetings SET Minutes=@json WHERE Tenant=@tenant AND Id=@id AND Created>DATEADD(day,-30,SYSDATETIMEOFFSET())", key); cmd.Parameters.AddWithValue("@json", JsonSerializer.Serialize(m, Json)); if (await cmd.ExecuteNonQueryAsync(ct) != 1) throw new InvalidOperationException("Utløpt møte."); }
    public async Task<IReadOnlyList<MeetingSession>> ActiveAsync(CancellationToken ct) { await using var c = await Open(ct); using var cmd = Command(c, "SELECT Json FROM Meetings WHERE Tenant=@tenant AND (JSON_VALUE(Json,'$.state')='0' OR JSON_VALUE(Json,'$.state')='1')"); await using var r = await cmd.ExecuteReaderAsync(ct); var result = new List<MeetingSession>(); while (await r.ReadAsync(ct)) result.Add(JsonSerializer.Deserialize<MeetingSession>(r.GetString(0), Json)!); return result; }
    public async Task<IReadOnlyList<MeetingKey>> PendingAsync(CancellationToken ct) { await using var c = await Open(ct); using var cmd = Command(c, "SELECT Json FROM Meetings WHERE Tenant=@tenant AND Created>DATEADD(day,-30,SYSDATETIMEOFFSET()) AND DeliveryFinished=0 AND JSON_VALUE(Json,'$.readyForFinalization')='true' AND (JSON_VALUE(Json,'$.state')='2' OR JSON_VALUE(Json,'$.state')='3')"); await using var r = await cmd.ExecuteReaderAsync(ct); var result = new List<MeetingKey>(); while (await r.ReadAsync(ct)) result.Add(JsonSerializer.Deserialize<MeetingSession>(r.GetString(0), Json)!.Key); return result; }
    public async Task<bool> TryLeaseAsync(MeetingKey key, string owner, CancellationToken ct) { await using var c = await Open(ct); using var cmd = Command(c, "UPDATE Meetings SET LeaseOwner=@owner,LeaseUntil=DATEADD(minute,10,SYSDATETIMEOFFSET()) WHERE Tenant=@tenant AND Id=@id AND (LeaseUntil IS NULL OR LeaseUntil<SYSDATETIMEOFFSET()) AND Created>DATEADD(day,-30,SYSDATETIMEOFFSET())", key); cmd.Parameters.AddWithValue("@owner", owner); return await cmd.ExecuteNonQueryAsync(ct) == 1; }
    public async Task ReleaseAsync(MeetingKey key, string owner, CancellationToken ct) { await using var c = await Open(ct); using var cmd = Command(c, "UPDATE Meetings SET LeaseOwner=NULL,LeaseUntil=NULL WHERE Tenant=@tenant AND Id=@id AND LeaseOwner=@owner", key); cmd.Parameters.AddWithValue("@owner", owner); await cmd.ExecuteNonQueryAsync(ct); }
    public async Task<DeliveryOutcome?> ReserveDeliveryAsync(MeetingKey key, string recipient, CancellationToken ct)
    {
        await using var c = await Open(ct); await using var tx = (SqlTransaction)await c.BeginTransactionAsync(IsolationLevel.Serializable, ct);
        using var read = Command(c, "SELECT Outcome FROM Deliveries WITH (UPDLOCK,HOLDLOCK) WHERE Tenant=@tenant AND MeetingId=@id AND RecipientId=@recipient", key, tx); read.Parameters.AddWithValue("@recipient", Hash(recipient.ToLowerInvariant())); var prior = await read.ExecuteScalarAsync(ct);
        if (prior is not null) { await tx.CommitAsync(ct); return (DeliveryOutcome)Convert.ToInt32(prior); }
        using var write = Command(c, "INSERT Deliveries(Tenant,MeetingId,RecipientId,Recipient,Outcome) VALUES(@tenant,@id,@recipient,@email,2)", key, tx); write.Parameters.AddWithValue("@recipient", Hash(recipient.ToLowerInvariant())); write.Parameters.AddWithValue("@email", recipient); await write.ExecuteNonQueryAsync(ct); await tx.CommitAsync(ct); return null;
    }
    public async Task CompleteDeliveryAsync(MeetingKey key, string recipient, DeliveryOutcome outcome, CancellationToken ct) { await using var c = await Open(ct); using var cmd = Command(c, "UPDATE Deliveries SET Outcome=@outcome WHERE Tenant=@tenant AND MeetingId=@id AND RecipientId=@recipient", key); cmd.Parameters.AddWithValue("@recipient", Hash(recipient.ToLowerInvariant())); cmd.Parameters.AddWithValue("@outcome", (int)outcome); await cmd.ExecuteNonQueryAsync(ct); }
    public async Task MarkDeliveredAsync(MeetingKey key, DeliveryReport report, CancellationToken ct) { await using var c = await Open(ct); using var cmd = Command(c, "UPDATE Meetings SET DeliveryFinished=1,DeliveryReport=@report WHERE Tenant=@tenant AND Id=@id", key); cmd.Parameters.AddWithValue("@report", JsonSerializer.Serialize(report, Json)); await cmd.ExecuteNonQueryAsync(ct); }
    public async Task<int> DeleteExpiredAsync(DateTimeOffset now, CancellationToken ct) { await using var c = await Open(ct); using var cmd = Command(c, "DELETE FROM Conversations WHERE Tenant=@tenant AND Updated<=@cutoff; DELETE FROM Meetings WHERE Tenant=@tenant AND Created<=@cutoff"); cmd.Parameters.AddWithValue("@cutoff", now.AddDays(-30)); return await cmd.ExecuteNonQueryAsync(ct); }
    public async Task SaveConversationAsync(string threadId, string reference, CancellationToken ct) { await using var c = await Open(ct); await using var tx = (SqlTransaction)await c.BeginTransactionAsync(IsolationLevel.Serializable, ct); using var cmd = Command(c, "IF EXISTS(SELECT 1 FROM Conversations WITH (UPDLOCK,HOLDLOCK) WHERE Tenant=@tenant AND Id=@id) UPDATE Conversations SET Json=@json,Updated=SYSDATETIMEOFFSET() WHERE Tenant=@tenant AND Id=@id ELSE INSERT Conversations(Tenant,Id,Json,Updated) VALUES(@tenant,@id,@json,SYSDATETIMEOFFSET())", tx: tx); cmd.Parameters.AddWithValue("@id", Hash(threadId)); cmd.Parameters.AddWithValue("@json", reference); await cmd.ExecuteNonQueryAsync(ct); await tx.CommitAsync(ct); }
    public async Task<string?> GetConversationAsync(string threadId, CancellationToken ct) { await using var c = await Open(ct); using var cmd = Command(c, "SELECT Json FROM Conversations WHERE Tenant=@tenant AND Id=@id"); cmd.Parameters.AddWithValue("@id", Hash(threadId)); return await cmd.ExecuteScalarAsync(ct) as string; }
    public async Task InitializeAsync(CancellationToken ct) { await using var c = await Open(ct); using var cmd = c.CreateCommand(); cmd.CommandText = Schema; await cmd.ExecuteNonQueryAsync(ct); }
    const string Schema = """
 IF OBJECT_ID('Meetings') IS NULL CREATE TABLE Meetings(Tenant uniqueidentifier NOT NULL,Id char(64) NOT NULL,Created datetimeoffset NOT NULL,Json nvarchar(max) NOT NULL,Minutes nvarchar(max) NULL,LeaseOwner nvarchar(64) NULL,LeaseUntil datetimeoffset NULL,DeliveryFinished bit NOT NULL DEFAULT 0,DeliveryReport nvarchar(max) NULL,PRIMARY KEY(Tenant,Id));
 IF OBJECT_ID('Segments') IS NULL CREATE TABLE Segments(Tenant uniqueidentifier NOT NULL,MeetingId char(64) NOT NULL,SegmentId char(64) NOT NULL,Json nvarchar(max) NOT NULL,PRIMARY KEY(Tenant,MeetingId,SegmentId),FOREIGN KEY(Tenant,MeetingId) REFERENCES Meetings(Tenant,Id) ON DELETE CASCADE);
 IF OBJECT_ID('Deliveries') IS NULL CREATE TABLE Deliveries(Tenant uniqueidentifier NOT NULL,MeetingId char(64) NOT NULL,RecipientId char(64) NOT NULL,Recipient nvarchar(320) NOT NULL,Outcome int NOT NULL,PRIMARY KEY(Tenant,MeetingId,RecipientId),FOREIGN KEY(Tenant,MeetingId) REFERENCES Meetings(Tenant,Id) ON DELETE CASCADE);
 IF OBJECT_ID('Conversations') IS NULL CREATE TABLE Conversations(Tenant uniqueidentifier NOT NULL,Id char(64) NOT NULL,Json nvarchar(max) NOT NULL,Updated datetimeoffset NOT NULL,PRIMARY KEY(Tenant,Id));
 """;
}
